#include <cstdio>
#include <vector>
#include <cstring>
#include <algorithm>

std::vector<long long> st, mn;

int main() {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; ++i) {
        char op[16];
        scanf("%s", op);
        if (strcmp(op, "push") == 0) {
            long long x; scanf("%lld", &x);
            st.push_back(x);
            mn.push_back(mn.empty() ? x : std::min(mn.back(), x));
        } else if (strcmp(op, "pop") == 0) {
            st.pop_back();
            mn.pop_back();
        } else if (strcmp(op, "top") == 0) {
            printf("%lld\n", st.back());
        } else if (strcmp(op, "getMin") == 0) {
            printf("%lld\n", mn.back());
        }
    }
    return 0;
}
